  function mount(host, bv) {
    const frames=framesById[bv];
    if (!host || !frames) return;
    const root=document.createElement('details');
    root.className='composition-study';
    root.open=true;
    root.innerHTML='<summary>色块构图</summary><div class="composition-body"><div class="composition-screen"><div class="composition-tiles" role="img"></div></div><div class="composition-side"><div class="composition-frames" aria-label="选择参考画面"></div><p class="composition-caption"></p><div class="composition-inks" aria-label="选择颜色"></div><output class="composition-readout" aria-live="polite"></output></div></div>';
    host.replaceChildren(root);
    const board=root.querySelector('.composition-tiles'), buttons=root.querySelector('.composition-frames'), inks=root.querySelector('.composition-inks'), output=root.querySelector('output');
    root.querySelector('.composition-caption').textContent=(frames.length===1?'按原片封面':'按时间顺序取三个预览画面')+'，把画面归纳为明暗与色块。点色票查看大致占比。';
    let frameIndex=0, colorIndex=-1;
    const labels=frames.length===1?['封面']:['前段','中段','后段'];
    labels.forEach((label,i)=>{
      const btn=document.createElement('button');btn.type='button';btn.textContent=label;
      btn.onclick=()=>{frameIndex=i;colorIndex=-1;paint();};buttons.append(btn);
    });
    function selectColor(index){
      colorIndex=index===colorIndex?-1:index;
      const [colors,cells]=frames[frameIndex];
      const count=[...cells].filter(c=>Number(c)===colorIndex).length;
      [...board.children].forEach((el,i)=>el.classList.toggle('quiet',colorIndex!==-1 && Number(cells[i])!==colorIndex));
      [...inks.children].forEach((el,i)=>el.setAttribute('aria-pressed',String(i===colorIndex)));
      output.textContent=colorIndex===-1?'全幅构图 · '+colors.length+' 个代表色':colors[colorIndex].toUpperCase()+' · 约占 '+Math.round(count/cells.length*100)+'%';
    }
    function paint(){
      const [colors,cells]=frames[frameIndex];
      [...buttons.children].forEach((btn,i)=>btn.setAttribute('aria-pressed',String(i===frameIndex)));
      board.setAttribute('aria-label',labels[frameIndex]+'的抽象色块构图');board.replaceChildren();inks.replaceChildren();
      const pixels=document.createDocumentFragment();
      for(const index of cells){const tile=document.createElement('i');tile.style.backgroundColor=colors[Number(index)];tile.onclick=()=>selectColor(Number(index));pixels.append(tile);}
      board.append(pixels);
      colors.forEach((hex,i)=>{const b=document.createElement('button');b.type='button';b.style.setProperty('--swatch',hex);b.title=hex.toUpperCase();b.setAttribute('aria-label','查看 '+hex.toUpperCase()+' 的面积');b.onclick=()=>selectColor(i);inks.append(b);});
      selectColor(-1);
    }
    paint();
  }
  window.AtlasComposition={mount};
